    public static void main(String[] args) {
        launch(args);
    }
}

package com.auction.server;

import java.net.InetSocketAddress;
import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ConcurrentHashMap;
import org.java_websocket.WebSocket;
import org.java_websocket.handshake.ClientHandshake;
import org.java_websocket.server.WebSocketServer;
import org.json.JSONObject;

/**
 * WebSocket Server cho Auction System
 * Broadcast cập nhật giá, trạng thái đấu giá realtime tới tất cả clients
 */
public class AuctionWebSocketServer extends WebSocketServer {
    private static final int WEBSOCKET_PORT = 8081;
    private static AuctionWebSocketServer instance;

    // Lưu trữ clients kết nối tới từng item (auction room)
    // Key: itemId, Value: List<WebSocket>
    private final Map<Integer, List<WebSocket>> itemSubscribers = new ConcurrentHashMap<>();

    private AuctionWebSocketServer() {
        super(new InetSocketAddress("0.0.0.0", WEBSOCKET_PORT));
        System.out.println(" WebSocket Server khởi tạo trên port " + WEBSOCKET_PORT);
    }

    /**
     * Singleton pattern - dùng 1 instance duy nhất
     */
    public static synchronized AuctionWebSocketServer getInstance() {
        if (instance == null) {
            instance = new AuctionWebSocketServer();
        }
        return instance;
    }

    @Override
    public void onOpen(WebSocket conn, ClientHandshake handshake) {
        System.out.println("✅ Client mới kết nối: " + conn.getRemoteSocketAddress());
    }

    /**
     * Nhận message từ client
     * Format: {"action": "SUBSCRIBE", "itemId": 123}
     *         {"action": "UNSUBSCRIBE", "itemId": 123}
     */
    @Override
    public void onMessage(WebSocket conn, String message) {
        try {
            JSONObject json = new JSONObject(message);
            String action = json.optString("action", "");

            if ("SUBSCRIBE".equals(action)) {
                int itemId = json.getInt("itemId");
                itemSubscribers.computeIfAbsent(itemId, k -> new CopyOnWriteArrayList<>()).add(conn);
                System.out.println(" Client subscribe itemId: " + itemId);

                // Gửi confirmation
                JSONObject response = new JSONObject();
                response.put("type", "SUBSCRIBED");
                response.put("itemId", itemId);
                conn.send(response.toString());

            } else if ("UNSUBSCRIBE".equals(action)) {
                int itemId = json.getInt("itemId");
                List<WebSocket> subscribers = itemSubscribers.get(itemId);
                if (subscribers != null) {
                    subscribers.remove(conn);
                }
                System.out.println(" Client unsubscribe itemId: " + itemId);
            }
        } catch (Exception e) {
            System.err.println("❌ Lỗi xử lý WebSocket message: " + e.getMessage());
        }
    }

    @Override
    public void onClose(WebSocket conn, int code, String reason, boolean remote) {
        System.out.println("❌ Client ngắt kết nối: " + conn.getRemoteSocketAddress());
        // Xóa client khỏi tất cả subscribers
        itemSubscribers.values().forEach(list -> list.remove(conn));
    }

    @Override
    public void onError(WebSocket conn, Exception ex) {
        System.err.println("⚠️ WebSocket error: " + ex.getMessage());
        ex.printStackTrace();
    }

    @Override
    public void onStart() {
        System.out.println(" WebSocket Server đã khởi động!");
    }

    /**
     * Broadcast cập nhật giá cho tất cả clients đang theo dõi item này
     *
     * @param itemId ID sản phẩm
     * @param currentPrice Giá hiện tại
     * @param bidderId ID người đặt giá
     * @param binderName Tên người đặt giá
     */
    public void broadcastPriceUpdate(int itemId, double currentPrice, int bidderId, String binderName) {
        List<WebSocket> subscribers = itemSubscribers.get(itemId);
        if (subscribers != null && !subscribers.isEmpty()) {
            JSONObject message = new JSONObject();
            message.put("type", "PRICE_UPDATE");
            message.put("itemId", itemId);
            message.put("currentPrice", currentPrice);
            message.put("bidderId", bidderId);
            message.put("bidderName", binderName);
            message.put("timestamp", System.currentTimeMillis());

            String payload = message.toString();
            subscribers.forEach(conn -> {
                try {
                    conn.send(payload);
                } catch (Exception e) {
                    System.err.println("Lỗi gửi PRICE_UPDATE: " + e.getMessage());
                }
            });

            System.out.println(" Broadcast PRICE_UPDATE itemId=" + itemId + " price=" + currentPrice + " -> " + subscribers.size() + " clients");
        }
    }

    /**
     * Broadcast cập nhật số người tham gia
     */
    public void broadcastParticipantUpdate(int itemId, int participantCount) {
        List<WebSocket> subscribers = itemSubscribers.get(itemId);
        if (subscribers != null && !subscribers.isEmpty()) {
            JSONObject message = new JSONObject();
            message.put("type", "PARTICIPANT_UPDATE");
            message.put("itemId", itemId);
            message.put("participantCount", participantCount);
            message.put("timestamp", System.currentTimeMillis());

            String payload = message.toString();
            subscribers.forEach(conn -> {
                try {
                    conn.send(payload);
                } catch (Exception e) {
                    System.err.println("Lỗi gửi PARTICIPANT_UPDATE: " + e.getMessage());
                }
            });
        }
    }

    /**
     * Broadcast khi phiên đấu giá kết thúc
     */
    public void broadcastAuctionFinished(int itemId, double finalPrice, int winnerId, String winnerName) {
        List<WebSocket> subscribers = itemSubscribers.get(itemId);
        if (subscribers != null && !subscribers.isEmpty()) {
            JSONObject message = new JSONObject();
            message.put("type", "AUCTION_FINISHED");
            message.put("itemId", itemId);
            message.put("finalPrice", finalPrice);
            message.put("winnerId", winnerId);
            message.put("winnerName", winnerName);
            message.put("timestamp", System.currentTimeMillis());

            String payload = message.toString();
            subscribers.forEach(conn -> {
                try {
                    conn.send(payload);
                } catch (Exception e) {
                    System.err.println("Lỗi gửi AUCTION_FINISHED: " + e.getMessage());
                }
            });
        }
    }

    /**
     * Broadcast timer extend khi có bid trong 2 phút cuối
     */
    public void broadcastTimerExtended(int itemId, int newTimeRemaining) {
        List<WebSocket> subscribers = itemSubscribers.get(itemId);
        if (subscribers != null && !subscribers.isEmpty()) {
            JSONObject message = new JSONObject();
            message.put("type", "TIMER_EXTENDED");
            message.put("itemId", itemId);
            message.put("newTimeRemaining", newTimeRemaining);
            message.put("timestamp", System.currentTimeMillis());

            String payload = message.toString();
            subscribers.forEach(conn -> {
                try {
                    conn.send(payload);
                } catch (Exception e) {
                    System.err.println("Lỗi gửi TIMER_EXTENDED: " + e.getMessage());
                }
            });
        }
    }
}

package com.auction.server;

import java.io.*;
import java.net.Socket;
import java.util.List;
import org.json.JSONArray;
import org.json.JSONObject;
import com.auction.service.ProductService;
import com.auction.database.BidDAO;

/**
 *  ClientHandler = "Người phục vụ" mỗi client
 *
 * Mỗi client (App JavaFX) kết nối → Server tạo 1 ClientHandler
 * ClientHandler chịu trách nhiệm:
 * ✓ Đọc command từ client
 * ✓ Xử lý command
 * ✓ Gửi response về client
 */
public class ClientHandler implements Runnable {
    private final Socket clientSocket;  // Cái "ống" để nói chuyện với client

    // ✨ TẠO INSTANCE
    public ClientHandler(Socket socket) {
        this.clientSocket = socket;
    }

    //  CHẠY THREAD
    @Override
    public void run() {
        try (Socket s = clientSocket;
             // InputStream = "Cái lỗ" để NHẬN dữ liệu từ client
             InputStream inputStream = s.getInputStream();
             // OutputStream = "Cái lỗ" để GỬI dữ liệu cho client
             OutputStream outputStream = s.getOutputStream()) {

            // CẤU HÌNH SOCKET
            s.setSoTimeout(10_000);  // Nếu đợi lâu hơn 10s mà ko có dữ liệu thì timeout

            System.out.println("✅ Client kết nối: " + s.getRemoteSocketAddress());

            // TẠO "CÁI ỐNG" ĐỂ ĐỌC/GHI DỮ LIỆU
            // BufferedReader = Đọc dữ liệu nhanh hơn, dễ dàng hơn
            BufferedReader br = new BufferedReader(
                new InputStreamReader(inputStream, "UTF-8")  // UTF-8 để hỗ trợ Tiếng Việt
            );

            // PrintWriter = Ghi dữ liệu, true = tự động flush (gửi ngay)
            PrintWriter pw = new PrintWriter(
                new OutputStreamWriter(outputStream, "UTF-8"),
                true  // auto-flush: gửi ngay lập tức
            );

            // LẶP VÔ HẠN - LẮNG NGHE TỪ CLIENT
            String jsonCommand;  // Biến chứa command từ client (JSON format)

            while ((jsonCommand = br.readLine()) != null) {
                // Nhận được 1 dòng text từ client
                System.out.println(" Nhận command: " + jsonCommand);

                try {
                    // PARSE JSON (phân tích dữ liệu)
                    JSONObject request = new JSONObject(jsonCommand);
                    String action = request.getString("action");  // Lấy "action"

                    // CHỌN XỬ LÝ THEO ACTION
                    JSONObject response = new JSONObject();

                    if ("GET_ITEMS".equals(action)) {
                        // CLIENT MUỐN XEM DANH SÁCH BIỂN SỐ
                        handleGetItems(request, response);
                    }
                    else if ("PLACE_BID".equals(action)) {
                        // CLIENT MUỐN ĐẤU GIÁ
                        handlePlaceBid(request, response);
                    }
                    else if ("GET_PENDING_ITEMS".equals(action)) {
                        // ADMIN XEM DANH SÁCH CHỜ DUYỆT
                        handleGetPendingItems(request, response);
                    }
                    else if ("APPROVE_ITEM".equals(action)) {
                        // ADMIN DUYỆT BIỂN SỐ
                        handleApproveItem(request, response);
                    }
                    else {
                        // ACTION KHÔNG NHẬN DẠng
                        response.put("status", "error");
                        response.put("message", "Action không hợp lệ: " + action);
                    }

                    // GỬI RESPONSE VỀ CLIENT
                    String jsonResponse = response.toString();
                    System.out.println("Gửi response: " + jsonResponse);
                    pw.println(jsonResponse);

                } catch (Exception e) {
                    //LỖI KHI PARSE JSON HOẶC XỬ LÝ
                    System.err.println("Lỗi xử lý: " + e.getMessage());

                    // GỬI ERROR RESPONSE VỀ CLIENT
                    JSONObject errorResponse = new JSONObject();
                    errorResponse.put("status", "error");
                    errorResponse.put("message", "Lỗi server: " + e.getMessage());
                    pw.println(errorResponse.toString());
                }
            }

            // KẾT THÚC KẾT NỐI
            System.out.println("Client ngắt kết nối: " + s.getRemoteSocketAddress());

        } catch (IOException e) {
            System.err.println("I/O error: " + e.getMessage());
        }
    }

    /**
     *HANDLE GET_ITEMS
     * Client yêu cầu: xem danh sách biển số đã duyệt
     */
    private void handleGetItems(JSONObject request, JSONObject response) {
        try {
            String type = request.optString("type", "Car");  // Mặc định là "Car"

            // LẤY DANH SÁCH TỬ DATABASE
            List<String[]> items = ProductService.getApprovedProductsByType(type);

            // CONVERT THÀNH JSON
            JSONArray itemsArray = new JSONArray();
            for (String[] item : items) {
                JSONObject itemObj = new JSONObject();
                itemObj.put("id", item[0]);
                itemObj.put("plate_number", item[1]);
                itemObj.put("start_price", item[2]);
                itemObj.put("current_price", item[3]);
                itemObj.put("description", item[4]);
                itemObj.put("vehicle_type", item[5]);
                itemsArray.put(itemObj);
            }

            // TẠO RESPONSE
            response.put("status", "success");
            response.put("items", itemsArray);
            response.put("count", items.size());

        } catch (Exception e) {
            response.put("status", "error");
            response.put("message", e.getMessage());
        }
    }

    /**
     * HANDLE PLACE_BID
     * Client muốn đấu giá (tăng giá)
     */
    private void handlePlaceBid(JSONObject request, JSONObject response) {
        try {
            int itemId = request.getInt("itemId");
            int userId = request.getInt("userId");  // Lấy user ID từ client
            double amount = request.getDouble("amount");

            //  LƯU VÀO DATABASE
            BidDAO.addBid(itemId, userId, amount);

            response.put("status", "success");
            response.put("message", "Đấu giá thành công");
            response.put("new_price", amount);

        } catch (Exception e) {
            response.put("status", "error");
            response.put("message", e.getMessage());
        }
    }

    /**
     * HANDLE GET_PENDING_ITEMS (ADMIN)
     * Xem danh sách biển số chờ duyệt
     */
    private void handleGetPendingItems(JSONObject request, JSONObject response) {
        try {
            List<String[]> pendingItems = ProductService.getPendingProducts();

            JSONArray itemsArray = new JSONArray();
            for (String[] item : pendingItems) {
                JSONObject itemObj = new JSONObject();
                itemObj.put("id", item[0]);
                itemObj.put("plate_number", item[1]);
                itemObj.put("description", item[4]);
                itemObj.put("seller_name", item[7]);  // Tên người bán
                itemsArray.put(itemObj);
            }

            response.put("status", "success");
            response.put("pending_items", itemsArray);

        } catch (Exception e) {
            response.put("status", "error");
            response.put("message", e.getMessage());
        }
    }

    /**
     * HANDLE APPROVE_ITEM (ADMIN)
     * Duyệt 1 biển số
     */
    private void handleApproveItem(JSONObject request, JSONObject response) {
        try {
            String plateNumber = request.getString("plate_number");

            boolean success = ProductService.approveProduct(plateNumber);

            if (success) {
                response.put("status", "success");
                response.put("message", "Duyệt biển số thành công");
            } else {
                response.put("status", "error");
                response.put("message", "Không thể duyệt biển số này");
            }

        } catch (Exception e) {
            response.put("status", "error");
            response.put("message", e.getMessage());
        }
    }
}

package com.auction.server;

import java.io.*;
import java.net.Socket;
import java.util.List;
import org.json.JSONArray;
import org.json.JSONObject;
import com.auction.service.ProductService;
import com.auction.database.BidDAO;
import com.auction.database.ItemDAO;
import com.auction.database.UserDAO;
import com.auction.model.User;

/**
 *  ClientHandler = "Người phục vụ" mỗi client
 *
 * Mỗi client (App JavaFX) kết nối → Server tạo 1 ClientHandler
 * ClientHandler chịu trách nhiệm:
 * ✓ Đọc command từ client
 * ✓ Xử lý command
 * ✓ Gửi response về client
 */
public class ClientHandler implements Runnable {
    private final Socket clientSocket;  // Cái "ống" để nói chuyện với client

    // ✨ TẠO INSTANCE
    public ClientHandler(Socket socket) {
        this.clientSocket = socket;
    }

    //  CHẠY THREAD
    @Override
    public void run() {
        try (Socket s = clientSocket;
             // InputStream = "Cái lỗ" để NHẬN dữ liệu từ client
             InputStream inputStream = s.getInputStream();
             // OutputStream = "Cái lỗ" để GỬI dữ liệu cho client
             OutputStream outputStream = s.getOutputStream()) {

            // CẤU HÌNH SOCKET
            s.setSoTimeout(10_000);  // Nếu đợi lâu hơn 10s mà ko có dữ liệu thì timeout

            System.out.println("✅ Client kết nối: " + s.getRemoteSocketAddress());

            // TẠO "CÁI ỐNG" ĐỂ ĐỌC/GHI DỮ LIỆU
            // BufferedReader = Đọc dữ liệu nhanh hơn, dễ dàng hơn
            BufferedReader br = new BufferedReader(
                new InputStreamReader(inputStream, "UTF-8")  // UTF-8 để hỗ trợ Tiếng Việt
            );

            // PrintWriter = Ghi dữ liệu, true = tự động flush (gửi ngay)
            PrintWriter pw = new PrintWriter(
                new OutputStreamWriter(outputStream, "UTF-8"),
                true  // auto-flush: gửi ngay lập tức
            );

            // LẶP VÔ HẠN - LẮNG NGHE TỪ CLIENT
            String jsonCommand;  // Biến chứa command từ client (JSON format)

            while ((jsonCommand = br.readLine()) != null) {
                // Nhận được 1 dòng text từ client
                System.out.println(" Nhận command: " + jsonCommand);

                try {
                    // PARSE JSON (phân tích dữ liệu)
                    JSONObject request = new JSONObject(jsonCommand);
                    String action = request.getString("action");  // Lấy "action"

                    // CHỌN XỬ LÝ THEO ACTION
                    JSONObject response = new JSONObject();

                    if ("GET_ITEMS".equals(action)) {
                        // CLIENT MUỐN XEM DANH SÁCH BIỂN SỐ
                        handleGetItems(request, response);
                    }
                    else if ("PLACE_BID".equals(action)) {
                        // CLIENT MUỐN ĐẤU GIÁ
                        handlePlaceBid(request, response);
                    }
                    else if ("GET_PENDING_ITEMS".equals(action)) {
                        // ADMIN XEM DANH SÁCH CHỜ DUYỆT
                        handleGetPendingItems(request, response);
                    }
                    else if ("APPROVE_ITEM".equals(action)) {
                        // ADMIN DUYỆT BIỂN SỐ
                        handleApproveItem(request, response);
                    }
                    else {
                        // ACTION KHÔNG NHẬN DẠng
                        response.put("status", "error");
                        response.put("message", "Action không hợp lệ: " + action);
                    }

                    // GỬI RESPONSE VỀ CLIENT
                    String jsonResponse = response.toString();
                    System.out.println("Gửi response: " + jsonResponse);
                    pw.println(jsonResponse);

                } catch (Exception e) {
                    //LỖI KHI PARSE JSON HOẶC XỬ LÝ
                    System.err.println("Lỗi xử lý: " + e.getMessage());

                    // GỬI ERROR RESPONSE VỀ CLIENT
                    JSONObject errorResponse = new JSONObject();
                    errorResponse.put("status", "error");
                    errorResponse.put("message", "Lỗi server: " + e.getMessage());
                    pw.println(errorResponse.toString());
                }
            }

            // KẾT THÚC KẾT NỐI
            System.out.println("Client ngắt kết nối: " + s.getRemoteSocketAddress());

        } catch (IOException e) {
            System.err.println("I/O error: " + e.getMessage());
        }
    }

    /**
     *HANDLE GET_ITEMS
     * Client yêu cầu: xem danh sách biển số đã duyệt
     */
    private void handleGetItems(JSONObject request, JSONObject response) {
        try {
            String type = request.optString("type", "Car");  // Mặc định là "Car"

            // LẤY DANH SÁCH TỬ DATABASE
            List<String[]> items = ProductService.getApprovedProductsByType(type);

            // CONVERT THÀNH JSON
            JSONArray itemsArray = new JSONArray();
            for (String[] item : items) {
                JSONObject itemObj = new JSONObject();
                itemObj.put("id", item[0]);
                itemObj.put("plate_number", item[1]);
                itemObj.put("start_price", item[2]);
                itemObj.put("current_price", item[3]);
                itemObj.put("description", item[4]);
                itemObj.put("vehicle_type", item[5]);
                itemsArray.put(itemObj);
            }

            // TẠO RESPONSE
            response.put("status", "success");
            response.put("items", itemsArray);
            response.put("count", items.size());

        } catch (Exception e) {
            response.put("status", "error");
            response.put("message", e.getMessage());
        }
    }

    /**
     * HANDLE PLACE_BID
     * Client muốn đấu giá (tăng giá)
     */
    private void handlePlaceBid(JSONObject request, JSONObject response) {
        try {
            int itemId = request.getInt("itemId");
            int userId = request.getInt("userId");  // Lấy user ID từ client
            double amount = request.getDouble("amount");

            //  LƯU VÀO DATABASE
            BidDAO.addBid(itemId, userId, amount);

            // Cập nhật giá hiện tại của item
            ItemDAO.updateCurrentPrice(itemId, amount);

            // ✅ BROADCAST giá mới qua WebSocket tới tất cả clients đang theo dõi
            AuctionWebSocketServer wsServer = AuctionWebSocketServer.getInstance();
            User user = UserDAO.getUserById(userId);
            String bidderName = (user != null) ? user.getFullName() : "Người dùng #" + userId;
            wsServer.broadcastPriceUpdate(itemId, amount, userId, bidderName);

            response.put("status", "success");
            response.put("message", "Đấu giá thành công");
            response.put("new_price", amount);

            System.out.println("✅ PLACE_BID: itemId=" + itemId + ", newPrice=" + amount + " - Broadcast to WebSocket");

        } catch (Exception e) {
            response.put("status", "error");
            response.put("message", e.getMessage());
            System.err.println("❌ Lỗi PLACE_BID: " + e.getMessage());
        }
    }

    /**
     * HANDLE GET_PENDING_ITEMS (ADMIN)
     * Xem danh sách biển số chờ duyệt
     */
    private void handleGetPendingItems(JSONObject request, JSONObject response) {
        try {
            List<String[]> pendingItems = ProductService.getPendingProducts();

            JSONArray itemsArray = new JSONArray();
            for (String[] item : pendingItems) {
                JSONObject itemObj = new JSONObject();
                itemObj.put("id", item[0]);
                itemObj.put("plate_number", item[1]);
                itemObj.put("description", item[4]);
                itemObj.put("seller_name", item[7]);  // Tên người bán
                itemsArray.put(itemObj);
            }

            response.put("status", "success");
            response.put("pending_items", itemsArray);

        } catch (Exception e) {
            response.put("status", "error");
            response.put("message", e.getMessage());
        }
    }

    /**
     * HANDLE APPROVE_ITEM (ADMIN)
     * Duyệt 1 biển số
     */
    private void handleApproveItem(JSONObject request, JSONObject response) {
        try {
            String plateNumber = request.getString("plate_number");

            boolean success = ProductService.approveProduct(plateNumber);

            if (success) {
                response.put("status", "success");
                response.put("message", "Duyệt biển số thành công");
            } else {
                response.put("status", "error");
                response.put("message", "Không thể duyệt biển số này");
            }

        } catch (Exception e) {
            response.put("status", "error");
            response.put("message", e.getMessage());
        }
    }
}
